mapper.select:
SELECT c.id, c.article_id, c.source_file_id, c.space_id, c.chunk_no, c.content, c.search_content, c.char_start, c.char_end, c.create_time, c.update_time FROM kb_article_chunk c JOIN kb_article a ON a.id = c.article_id WHERE c.space_id = #{spaceId} AND a.deleted = 0
AND a.status = #{status}
AND (
LOWER(c.search_content) LIKE CONCAT('%', #{token}, '%')
)
ORDER BY
(CASE WHEN LOWER(COALESCE(a.title, '')) LIKE CONCAT('%', #{token}, '%') THEN 4 ELSE 0 END + CASE WHEN LOWER(COALESCE(a.summary, '')) LIKE CONCAT('%', #{token}, '%') THEN 2 ELSE 0 END + CASE WHEN LOWER(c.search_content) LIKE CONCAT('%', #{token}, '%') THEN 1 ELSE 0 END) DESC,
c.article_id DESC, c.chunk_no ASC LIMIT #{limit}

SELECT c.id, c.article_id, c.source_file_id, c.space_id, c.chunk_no, c.content, c.search_content, c.char_start, c.char_end, c.create_time, c.update_time, 1 - (c.embedding <=> CAST(#{embedding} AS vector)) AS similarity FROM kb_article_chunk c JOIN kb_article a ON a.id = c.article_id WHERE c.space_id = #{spaceId} AND a.deleted = 0 AND c.embedding IS NOT NULL
AND a.status = #{status}
ORDER BY c.embedding <=> CAST(#{embedding} AS vector), c.article_id DESC, c.chunk_no ASC LIMIT #{limit}
